#!/usr/bin/env bash
# Correctifs tRPC : empreinte de mot de passe renvoyée par user.delete, erreurs internes exposées au navigateur,
# règles « pas soi-même » garanties côté serveur, gardes admin dans la chaîne, ctx.user retiré, ménage.
# Prérequis : apply-fix-like-messages-pg.sh (et l'incrément « droit à l'image — front »). Aucune migration.
# Usage (racine du repo) : bash apply-fix-trpc-gardes.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"packages/backend/src/trpc/core.ts" 2>/dev/null | grep -qF "errorFormatter"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "const likePrefix" "packages/backend/src/modules/storage/adapters/r2/r2StorageAdapter.ts" 2>/dev/null || { echo "❌ lancer d'abord apply-fix-like-messages-pg.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/api/trpc.mdx" "apps/web/content/docs/dev/auth/authentification.mdx" "apps/web/content/docs/dev/contenu/reglages-du-site.mdx" "apps/web/content/docs/dev/demarrer/facon-de-travailler.mdx" "apps/web/content/docs/dev/membres/profil-et-premiere-connexion.mdx" "apps/web/content/docs/dev/stockage/envoyer-et-servir-un-fichier.mdx" "apps/web/content/docs/dev/stockage/le-finder.mdx" "apps/web/src/app/(admin)/dashboard/groups/[id]/page.tsx" "apps/web/src/app/api/trpc/[trpc]/route.ts" "apps/web/src/core/trpc/trpcClient.ts" "packages/backend/src/modules/auth/router.ts" "packages/backend/src/modules/media/services/countPersoImages.service.ts" "packages/backend/src/modules/memberGroups/router.ts" "packages/backend/src/modules/pageVisibility/router.ts" "packages/backend/src/modules/sitePartners/router.ts" "packages/backend/src/modules/siteSettings/router.ts" "packages/backend/src/modules/storage/adapters/r2/r2StorageAdapter.ts" "packages/backend/src/modules/storage/router.ts" "packages/backend/src/modules/storage/services/resolvePendingUploadFolder.service.ts" "packages/backend/src/modules/trash/router.ts" "packages/backend/src/modules/users/router.ts" "packages/backend/src/trpc/core.ts" "scripts/build-procedure-map.mjs")
EXPECT=("32070ae9b8f0:apps/web/content/docs/dev/api/trpc.mdx" "4af5a521f340:apps/web/content/docs/dev/auth/authentification.mdx" "cbfa85dc63f3:apps/web/content/docs/dev/contenu/reglages-du-site.mdx" "7545a649ee19:apps/web/content/docs/dev/demarrer/facon-de-travailler.mdx" "01719a9cc417:apps/web/content/docs/dev/membres/profil-et-premiere-connexion.mdx" "7ceddc283950:apps/web/content/docs/dev/stockage/envoyer-et-servir-un-fichier.mdx" "7dcabeb7a3a0:apps/web/content/docs/dev/stockage/le-finder.mdx" "cc0b4d29986b:apps/web/src/app/(admin)/dashboard/groups/[id]/page.tsx" "fab2b481c6b4:apps/web/src/app/api/trpc/[trpc]/route.ts" "ec0fef2c32f0:apps/web/src/core/trpc/trpcClient.ts" "90f9ba8ae7b5:packages/backend/src/modules/auth/router.ts" "f7b908912dcb:packages/backend/src/modules/media/services/countPersoImages.service.ts" "c5ab025661b6:packages/backend/src/modules/memberGroups/router.ts" "41afe404aaf2:packages/backend/src/modules/pageVisibility/router.ts" "13e92229aa6d:packages/backend/src/modules/sitePartners/router.ts" "e585bbc98757:packages/backend/src/modules/siteSettings/router.ts" "9770ed4f7256:packages/backend/src/modules/storage/adapters/r2/r2StorageAdapter.ts" "d2faa520e085:packages/backend/src/modules/storage/router.ts" "a15a128fc212:packages/backend/src/modules/storage/services/resolvePendingUploadFolder.service.ts" "b81cddbc6067:packages/backend/src/modules/trash/router.ts" "7b5ede3fc3a3:packages/backend/src/modules/users/router.ts" "b0179fd72d73:packages/backend/src/trpc/core.ts" "a0242e2ce049:scripts/build-procedure-map.mjs")
