# Lien du formulaire pré-rempli : attribut download (règle de lint), seulement si rien ne règle déjà la question.
F=apps/web/src/features/image-consent/OnlineConsentForm.tsx
if [ -f "$F" ] && grep -qF '<a href="/api/media/image-consent/prefilled" className=' "$F" && ! grep -qF 'no-html-link-for-pages' "$F"; then
  if ! git diff --quiet HEAD -- "$F"; then echo "❌ $F a des modifications non commitées"; restore; exit 1; fi
  MODIFIED+=("$F")
  python3 - "$F" <<'PY2'
import sys
p = sys.argv[1]; s = open(p, encoding="utf-8").read()
a = '<a href="/api/media/image-consent/prefilled" className='
assert s.count(a) == 1
open(p, "w", encoding="utf-8").write(s.replace(a, '<a href="/api/media/image-consent/prefilled" download className='))
PY2
fi
[ "${AKFC_APPLY_ONLY:-0}" = "1" ] && { echo "Appliqué (sans vérification ni commit)."; exit 0; }
node scripts/build-procedure-map.mjs --write >/dev/null 2>&1 || { echo "❌ carte des procédures : échec"; restore; exit 1; }
echo "== pnpm check =="
if pgrep -f "next dev" >/dev/null 2>&1; then
  echo "  (pnpm dev tourne : vérification sans effacer .next)"
  CHECK="node scripts/check-next-conventions.mjs && node scripts/check-tour-targets.mjs && pnpm --filter backend typecheck && pnpm typecheck && pnpm lint"
else
  CHECK="pnpm check"
fi
if ! bash -c "$CHECK" > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"
  grep -nE "error TS|✗ tutos|ERR_|Error:|EACCES|Permission denied" /tmp/akfc_tc.log | head -12
  echo "  … fin du journal :"; grep -v '^[[:space:]]*$' /tmp/akfc_tc.log | tail -15
  restore; exit 1
fi
echo "  ✅ check OK"
OLDF=packages/backend/src/trpc/trpcCaller.ts
if [ -e "$OLDF" ]; then git rm -q "$OLDF"; fi
git add "${MODIFIED[@]}" "${CREATED[@]}" apps/web/src/features/docs/entities/procedureMap.generated.json
